worlds.script:
verse.api.platform({
  id: "central-plaza",
  position: [0, 0.02, -2.6],
  scale: [6, 0.08, 2.2],
  color: "#87b7d4"
});

verse.api.sign({
  id: "plaza-label",
  text: "GEN VERSE PLAZA",
  position: [0, 0.09, -2.6],
  color: "#1d3557",
  size: 0.42
});

for (let i = 0; i < 8; i++) {
  const angle = (Math.PI * 2 * i) / 8;
  verse.api.tree({
    id: "ring-tree-" + i,
    position: [Math.cos(angle) * 9, 0, Math.sin(angle) * 9],
    scale: 1
  });
}
